   767→func (p *Builder) retrievePendingBlock() (*v1.ExecutionPayload, error) {
   768→	result := &engine.ExecutableData{}
   769→	if p.currId == nil {
   770→		return nil, errors.New("no payload id is cached")
   771→	}
   772→	err := p.execClient.CallContext(context.Background(), result, GetPayloadMethod, *p.currId)
   773→	if err != nil {
   774→		return nil, err
   775→	}
   776→	payloadEnv, err := modifyExecutionPayload(*result, big.NewInt(0), nil, nil)
   777→	if err != nil {
   778→		return nil, err
   779→	}
   780→	marshalledOutput, err := payloadEnv.ExecutionPayload.MarshalJSON()
   781→	if err != nil {
   782→		return nil, err
   783→	}
   784→	bellatrixPayload := &v1.ExecutionPayload{}
   785→	if err = json.Unmarshal(marshalledOutput, bellatrixPayload); err != nil {
   786→		return nil, err
   787→	}
   788→	p.currId = nil
   789→	return bellatrixPayload, nil
   790→}
