    10→var (
    11→	drExample = &DepositRequest{}
    12→	drSize    = drExample.SizeSSZ()
    13→	wrExample = &WithdrawalRequest{}
    14→	wrSize    = wrExample.SizeSSZ()
    15→	crExample = &ConsolidationRequest{}
    16→	crSize    = crExample.SizeSSZ()
