    19→const (
    20→	DepositRequestType = iota
    21→	WithdrawalRequestType
    22→	ConsolidationRequestType
    23→)
    24→
    25→// ExecutionRequestConfig ensures that we don't mix up the execution request params
    26→type ExecutionRequestLimits struct {
    27→	Deposits       uint64
    28→	Withdrawals    uint64
    29→	Consolidations uint64
    30→}
    31→
    32→func (ebe *ExecutionBundleElectra) GetDecodedExecutionRequests(limits ExecutionRequestLimits) (*ExecutionRequests, error) {
    33→	requests := &ExecutionRequests{}
    34→	var prevTypeNum *uint8
    35→	for i := range ebe.ExecutionRequests {
    36→		requestType, requestListInSSZBytes, err := decodeExecutionRequest(ebe.ExecutionRequests[i])
    37→		if err != nil {
    38→			return nil, err
    39→		}
    40→		if prevTypeNum != nil && *prevTypeNum >= requestType {
    41→			return nil, errors.New("invalid execution request type order or duplicate requests, requests should be in sorted order and unique")
    42→		}
    43→		prevTypeNum = &requestType
    44→		switch requestType {
    45→		case DepositRequestType:
    46→			drs, err := unmarshalDeposits(requestListInSSZBytes, limits.Deposits)
    47→			if err != nil {
    48→				return nil, err
    49→			}
    50→			requests.Deposits = drs
    51→		case WithdrawalRequestType:
    52→			wrs, err := unmarshalWithdrawals(requestListInSSZBytes, limits.Withdrawals)
    53→			if err != nil {
    54→				return nil, err
    55→			}
    56→			requests.Withdrawals = wrs
    57→		case ConsolidationRequestType:
    58→			crs, err := unmarshalConsolidations(requestListInSSZBytes, limits.Consolidations)
    59→			if err != nil {
    60→				return nil, err
    61→			}
    62→			requests.Consolidations = crs
    63→		default:
    64→			return nil, errors.Errorf("unsupported request type %d", requestType)
    65→		}
    66→	}
    67→	return requests, nil
    68→}
    69→
    70→func unmarshalDeposits(requestListInSSZBytes []byte, maxDepositRequests uint64) ([]*DepositRequest, error) {
    71→	if len(requestListInSSZBytes) < drSize {
    72→		return nil, fmt.Errorf("invalid deposit requests SSZ size, got %d expected at least %d", len(requestListInSSZBytes), drSize)
    73→	}
    74→	maxSSZsize := uint64(drSize) * maxDepositRequests
    75→	if uint64(len(requestListInSSZBytes)) > maxSSZsize {
    76→		return nil, fmt.Errorf("invalid deposit requests SSZ size, requests should not be more than the max per payload, got %d max %d", len(requestListInSSZBytes), maxSSZsize)
    77→	}
    78→	return unmarshalItems(requestListInSSZBytes, drSize, func() *DepositRequest { return &DepositRequest{} })
    79→}
    80→
    81→func unmarshalWithdrawals(requestListInSSZBytes []byte, maxWithdrawals uint64) ([]*WithdrawalRequest, error) {
    82→	if len(requestListInSSZBytes) < wrSize {
    83→		return nil, fmt.Errorf("invalid withdrawal requests SSZ size, got %d expected at least %d", len(requestListInSSZBytes), wrSize)
    84→	}
    85→	maxSSZsize := uint64(wrSize) * maxWithdrawals
    86→	if uint64(len(requestListInSSZBytes)) > maxSSZsize {
    87→		return nil, fmt.Errorf("invalid withdrawal requests SSZ size, requests should not be more than the max per payload, got %d max %d", len(requestListInSSZBytes), maxSSZsize)
    88→	}
    89→	return unmarshalItems(requestListInSSZBytes, wrSize, func() *WithdrawalRequest { return &WithdrawalRequest{} })
    90→}
    91→
    92→func unmarshalConsolidations(requestListInSSZBytes []byte, maxConsolidations uint64) ([]*ConsolidationRequest, error) {
    93→	if len(requestListInSSZBytes) < crSize {
    94→		return nil, fmt.Errorf("invalid consolidation requests SSZ size, got %d expected at least %d", len(requestListInSSZBytes), crSize)
    95→	}
    96→	maxSSZsize := uint64(crSize) * maxConsolidations
    97→	if uint64(len(requestListInSSZBytes)) > maxSSZsize {
    98→		return nil, fmt.Errorf("invalid consolidation requests SSZ size, requests should not be more than the max per payload, got %d max %d", len(requestListInSSZBytes), maxSSZsize)
    99→	}
   100→	return unmarshalItems(requestListInSSZBytes, crSize, func() *ConsolidationRequest { return &ConsolidationRequest{} })
   101→}
   102→
   103→func decodeExecutionRequest(req []byte) (typ uint8, data []byte, err error) {
   104→	if len(req) < 1 {
   105→		return 0, nil, errors.New("invalid execution request, length less than 1")
   106→	}
   107→	return req[0], req[1:], nil
   108→}
   109→
   110→func EncodeExecutionRequests(requests *ExecutionRequests) ([]hexutil.Bytes, error) {
   111→	if requests == nil {
   112→		return nil, errors.New("invalid execution requests")
   113→	}
   114→
   115→	requestsData := make([]hexutil.Bytes, 0)
   116→
   117→	// request types MUST be in sorted order starting from 0
   118→	if len(requests.Deposits) > 0 {
   119→		drBytes, err := marshalItems(requests.Deposits)
   120→		if err != nil {
   121→			return nil, errors.Wrap(err, "failed to marshal deposit requests")
   122→		}
   123→		requestData := []byte{DepositRequestType}
   124→		requestData = append(requestData, drBytes...)
   125→		requestsData = append(requestsData, requestData)
   126→	}
   127→	if len(requests.Withdrawals) > 0 {
   128→		wrBytes, err := marshalItems(requests.Withdrawals)
   129→		if err != nil {
   130→			return nil, errors.Wrap(err, "failed to marshal withdrawal requests")
   131→		}
   132→		requestData := []byte{WithdrawalRequestType}
   133→		requestData = append(requestData, wrBytes...)
   134→		requestsData = append(requestsData, requestData)
   135→	}
   136→	if len(requests.Consolidations) > 0 {
   137→		crBytes, err := marshalItems(requests.Consolidations)
   138→		if err != nil {
   139→			return nil, errors.Wrap(err, "failed to marshal consolidation requests")
   140→		}
   141→		requestData := []byte{ConsolidationRequestType}
   142→		requestData = append(requestData, crBytes...)
   143→		requestsData = append(requestsData, requestData)
   144→	}
   145→
   146→	return requestsData, nil
   147→}
   148→
   149→type sszUnmarshaler interface {
   150→	UnmarshalSSZ([]byte) error
   151→}
   152→
   153→type sszMarshaler interface {
   154→	MarshalSSZTo(buf []byte) ([]byte, error)
   155→	SizeSSZ() int
   156→}
   157→
   158→func marshalItems[T sszMarshaler](items []T) ([]byte, error) {
   159→	if len(items) == 0 {
   160→		return []byte{}, nil
   161→	}
   162→	size := items[0].SizeSSZ()
   163→	buf := make([]byte, 0, size*len(items))
   164→	var err error
   165→	for i, item := range items {
   166→		buf, err = item.MarshalSSZTo(buf)
   167→		if err != nil {
   168→			return nil, fmt.Errorf("failed to marshal item at index %d: %w", i, err)
   169→		}
   170→	}
   171→	return buf, nil
   172→}
   173→
   174→// Generic function to unmarshal items
   175→func unmarshalItems[T sszUnmarshaler](data []byte, itemSize int, newItem func() T) ([]T, error) {
   176→	if len(data)%itemSize != 0 {
   177→		return nil, fmt.Errorf("invalid data length: data size (%d) is not a multiple of item size (%d)", len(data), itemSize)
   178→	}
   179→	numItems := len(data) / itemSize
   180→	items := make([]T, numItems)
   181→	for i := range items {
   182→		itemBytes := data[i*itemSize : (i+1)*itemSize]
   183→		item := newItem()
   184→		if err := item.UnmarshalSSZ(itemBytes); err != nil {
   185→			return nil, fmt.Errorf("failed to unmarshal item at index %d: %w", i, err)
   186→		}
   187→		items[i] = item
   188→	}
   189→	return items, nil
   190→}
