   167→// NewService sets up a new instance with an ethclient when given a web3 endpoint as a string in the config.
   168→func NewService(ctx context.Context, opts ...Option) (*Service, error) {
   169→	ctx, cancel := context.WithCancel(ctx)
   170→	_ = cancel // govet fix for lost cancel. Cancel is handled in service.Stop()
   171→	var depositTrie cache.MerkleTree
   172→	var err error
   173→	depositTrie = depositsnapshot.NewDepositTree()
   174→	genState, err := transition.EmptyGenesisState()
   175→	if err != nil {
   176→		return nil, errors.Wrap(err, "could not set up genesis state")
   177→	}
   178→
   179→	s := &Service{
   180→		ctx:       ctx,
   181→		cancel:    cancel,
   182→		rpcClient: RPCClientEmpty{},
   183→		cfg: &config{
   184→			beaconNodeStatsUpdater: &NopBeaconNodeStatsUpdater{},
   185→			eth1HeaderReqLimit:     defaultEth1HeaderReqLimit,
   186→		},
   187→		latestEth1Data: &ethpb.LatestETH1Data{
   188→			BlockHeight:        0,
   189→			BlockTime:          0,
   190→			BlockHash:          []byte{},
   191→			LastRequestedBlock: 0,
   192→		},
   193→		headerCache: newHeaderCache(),
   194→		depositTrie: depositTrie,
   195→		chainStartData: &ethpb.ChainStartData{
   196→			Eth1Data:           &ethpb.Eth1Data{},
   197→			ChainstartDeposits: make([]*ethpb.Deposit, 0),
   198→		},
   199→		lastReceivedMerkleIndex: -1,
   200→		preGenesisState:         genState,
   201→		eth1HeadTicker:          time.NewTicker(time.Duration(params.BeaconConfig().SecondsPerETH1Block) * time.Second),
   202→		capabilityCache:         &capabilityCache{},
   203→	}
   204→
   205→	for _, opt := range opts {
   206→		if err := opt(s); err != nil {
   207→			return nil, err
   208→		}
   209→	}
   210→	s.initDepositRequests()
   211→	eth1Data, err := s.validPowchainData(ctx)
   212→	if err != nil {
   213→		return nil, errors.Wrap(err, "unable to validate powchain data")
   214→	}
   215→	if err := s.initializeEth1Data(ctx, eth1Data); err != nil {
   216→		return nil, err
   217→	}
   218→	return s, nil
   219→}
