   866→func dedupEndpoints(endpoints []string) []string {
   867→	selectionMap := make(map[string]bool)
   868→	newEndpoints := make([]string, 0, len(endpoints))
   869→	for _, point := range endpoints {
   870→		if selectionMap[point] {
   871→			continue
   872→		}
   873→		newEndpoints = append(newEndpoints, point)
   874→		selectionMap[point] = true
   875→	}
   876→	return newEndpoints
   877→}
